// Home-screen icon of an installed experience (iPhone "Add to Home Screen" + Android/desktop PWA).
// Each experience type installs with its own icon instead of the shared Q (Rani, 27.11.2026).
// The PNGs in public/icons/experiences are generated by scripts/generate-app-icons.mjs — to add a
// type, add it there, re-run the script and list it in GENERATED below.

export type AppIconSize = 180 | 192 | 512;

const GENERATED = new Set([
  'qtag', 'raffle', 'weeklycal', 'qvote', 'qstage', 'selfiebeam', 'wordcloud', 'riddle',
  'minigames', 'qchallenge', 'qbet', 'qtreasure', 'qhunt', 'link', 'pdf', 'image', 'gif', 'video',
  'thecode',
]);

const FALLBACK: Record<AppIconSize, string> = {
  180: '/icons/apple-touch-icon.png',
  192: '/icons/icon-192x192.png',
  512: '/icons/icon-512x512.png',
};

export function appIconUrl(type: string | undefined, size: AppIconSize): string {
  if (type === 'tenbool') return `/api/og/tenbool?icon=${size}`;
  if (type === 'socialwall') {
    return size === 180 ? '/play/social-wall/apple-icon.png' : size === 192 ? '/play/social-wall/icon-192.png' : '/play/social-wall/icon.png';
  }
  if (type && GENERATED.has(type)) return `/icons/experiences/${type}-${size}.png`;
  return FALLBACK[size];
}

/** The manifest `icons` array: 192 + 512, each as both `any` and `maskable` (full-bleed art). */
export function manifestIcons(type: string | undefined) {
  return ([192, 512] as const).flatMap((px) =>
    (['any', 'maskable'] as const).map((purpose) => ({
      src: appIconUrl(type, px),
      sizes: `${px}x${px}`,
      type: 'image/png',
      purpose,
    })),
  );
}
